import{_ as t,o as e,c as a,a2 as l}from"./chunks/framework.DV9MvnYb.js";const g=JSON.parse('{"title":"学习","description":"系统编程方向的学习路线与资料索引","frontmatter":{"title":"学习","description":"系统编程方向的学习路线与资料索引","sidebar":false},"headers":[],"relativePath":"study/index.md","filePath":"study/index.md","lastUpdated":1786544175000}'),o={name:"study/index.md"};function n(i,r,s,h,u,d){return e(),a("div",null,[...r[0]||(r[0]=[l('<h1 id="学习" tabindex="-1">学习 <a class="header-anchor" href="#学习" aria-label="Permalink to &quot;学习&quot;">​</a></h1><p>这里整理我正在关注的系统编程资料。它不是“全部看完”的完成清单，而是一张持续维护的路线图：先确定当前问题，再选择一份主材料和一份练习材料。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>如果你也在学习这个方向，可以先阅读<a href="/posts/2026-08-12-systems-learning-map">我的系统学习地图</a>，里面说明了各部分之间的关系和建议顺序。</p></div><h2 id="当前主线" tabindex="-1">当前主线 <a class="header-anchor" href="#当前主线" aria-label="Permalink to &quot;当前主线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>核心问题</th><th>预期输出</th></tr></thead><tbody><tr><td>Rust</td><td>如何安全、清晰地表达系统程序？</td><td>小工具、练习代码、概念笔记</td></tr><tr><td>操作系统</td><td>进程、内存和文件系统怎样工作？</td><td>内核实验、执行路径图</td></tr><tr><td>组成原理</td><td>软件抽象如何落到处理器和设备？</td><td>RTL 练习、调试记录</td></tr><tr><td>Linux 内核</td><td>真实内核如何实现这些机制？</td><td>调用链笔记、源码分析</td></tr></tbody></table><h2 id="rust" tabindex="-1">Rust <a class="header-anchor" href="#rust" aria-label="Permalink to &quot;Rust&quot;">​</a></h2><h3 id="主线阅读" tabindex="-1">主线阅读 <a class="header-anchor" href="#主线阅读" aria-label="Permalink to &quot;主线阅读&quot;">​</a></h3><ul><li><strong><a href="https://course.rs/about-book.html" target="_blank" rel="noreferrer">Rust 语言圣经</a></strong>：中文主教程，适合系统建立所有权、生命周期、类型与并发知识。</li><li><strong><a href="https://google.github.io/comprehensive-rust/zh-CN/index.html" target="_blank" rel="noreferrer">Comprehensive Rust</a></strong>：内容紧凑，适合有其他语言基础时快速过一遍，也适合复习。</li></ul><h3 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h3><ul><li><strong><a href="https://colobu.com/rust100/" target="_blank" rel="noreferrer">100 Exercises to Learn Rust</a></strong>：短小、连续的练习，用来把概念变成肌肉记忆。</li><li><strong><a href="https://www.bookstack.cn/read/rustlang-cn-rust-algos/README.md" target="_blank" rel="noreferrer">Rust Algorithm Solutions</a></strong>：通过算法题熟悉容器、迭代器与所有权写法。</li><li><strong><a href="https://rustmagazine.github.io/rust_magazine_2021/chapter_3/projects.html" target="_blank" rel="noreferrer">Rust Learning Projects</a></strong>：寻找合适的小项目，把语言知识带入完整程序。</li></ul><h2 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;操作系统&quot;">​</a></h2><h3 id="建立概念" tabindex="-1">建立概念 <a class="header-anchor" href="#建立概念" aria-label="Permalink to &quot;建立概念&quot;">​</a></h3><ul><li><strong><a href="https://jyywiki.cn/OS/2024/" target="_blank" rel="noreferrer">操作系统：设计与实现</a></strong>：从程序和真实问题出发理解操作系统抽象，适合作为理论主线。</li></ul><h3 id="完成实验" tabindex="-1">完成实验 <a class="header-anchor" href="#完成实验" aria-label="Permalink to &quot;完成实验&quot;">​</a></h3><ul><li><strong><a href="https://rcore-os.cn/rCore-Tutorial-Book-v3/index.html" target="_blank" rel="noreferrer">rCore Tutorial v3</a></strong>：用 Rust 逐步实现教学内核，连接语言、体系结构和操作系统知识。</li><li><strong><a href="https://learningos.cn/rCore-Tutorial-Guide-2025S/0setup-devel-env.html" target="_blank" rel="noreferrer">rCore Tutorial Guide 2025S</a></strong>：实验环境、任务要求与排错入口。</li><li><strong><a href="https://oslearning365.github.io/arceos-tutorial-book/" target="_blank" rel="noreferrer">ArceOS Tutorial Book</a></strong>：了解组件化内核的构造方式，适合在完成基础实验后继续阅读。</li></ul><h3 id="社区与训练营" tabindex="-1">社区与训练营 <a class="header-anchor" href="#社区与训练营" aria-label="Permalink to &quot;社区与训练营&quot;">​</a></h3><ul><li><strong><a href="https://opencamp.cn/EulixOS/camp/202501" target="_blank" rel="noreferrer">EulixOS Community</a></strong>：开源操作系统相关课程与活动。</li><li><strong><a href="https://opencamp.ai/os2edu" target="_blank" rel="noreferrer">Open Source OS Community</a></strong>：操作系统学习社区和开放课程入口。</li></ul><h2 id="计算机组成与-verilog" tabindex="-1">计算机组成与 Verilog <a class="header-anchor" href="#计算机组成与-verilog" aria-label="Permalink to &quot;计算机组成与 Verilog&quot;">​</a></h2><ul><li><strong><a href="https://ysyx.oscc.cc/docs/" target="_blank" rel="noreferrer">一生一芯讲义</a></strong>：从程序运行一路深入到处理器实现，适合作为计算机系统主线。</li><li><strong><a href="https://hdlbits.01xz.net/wiki/Main_Page" target="_blank" rel="noreferrer">HDLBits</a></strong>：在线 Verilog 练习平台，可用于巩固组合逻辑、时序逻辑和有限状态机。</li></ul><p>学习这部分时，重点不是堆积 HDL 语法，而是建立“指令—处理器状态—硬件信号”之间的联系。</p><h2 id="linux-内核" tabindex="-1">Linux 内核 <a class="header-anchor" href="#linux-内核" aria-label="Permalink to &quot;Linux 内核&quot;">​</a></h2><ul><li><strong><a href="https://elixir.bootlin.com/linux/v6.13.7/source" target="_blank" rel="noreferrer">Linux Kernel Source</a></strong>：支持符号搜索和交叉引用，适合追踪函数、结构体与调用关系。</li><li><strong><a href="https://www.kernel.org/doc/html/latest/" target="_blank" rel="noreferrer">Linux Kernel Documentation</a></strong>：内核官方文档；遇到具体子系统时优先从这里查起。</li><li><strong><a href="https://www.kerneltravel.net/" target="_blank" rel="noreferrer">Linux Kernel Journey</a></strong>：中文内核社区及技术文章入口。</li></ul><p>阅读源码时，我会尽量从一个具体入口切入，例如一次系统调用、一个 <code>/proc</code> 节点或一次中断，而不是按目录顺序浏览整个内核。</p><h2 id="ai-系统" tabindex="-1">AI 系统 <a class="header-anchor" href="#ai-系统" aria-label="Permalink to &quot;AI 系统&quot;">​</a></h2><ul><li><strong><a href="https://opencamp.cn/InfiniTensor/camp/2024winter" target="_blank" rel="noreferrer">AI Systems Training Camp</a></strong>：从系统实现角度理解张量计算、算子与训练框架，可作为系统方向的拓展主题。</li></ul><p>这部分暂时作为拓展路线，不与当前的 Rust—操作系统—内核主线争夺优先级。</p><h2 id="学习记录原则" tabindex="-1">学习记录原则 <a class="header-anchor" href="#学习记录原则" aria-label="Permalink to &quot;学习记录原则&quot;">​</a></h2><ol><li>每次只解决一个足够具体的问题。</li><li>阅读后必须留下代码、图示、实验结果或简短总结中的至少一种。</li><li>资料重复时保留更清晰、更新更稳定的一份。</li><li>无法验证的理解标记为待确认，不把猜测写成结论。</li><li>每完成一个阶段，整理为一篇可以独立阅读的文章。</li></ol>',28)])])}const b=t(o,[["render",n]]);export{g as __pageData,b as default};
